/* eslint-disable */
/* global WebImporter */
/**
 * Parser: cards-product
 * Source: div[class*='Cards_wrapper'] (product cards grid)
 * One row per card: [image] [text]
 * Text cell order is load-bearing (blocks/cards-product/cards-product.js derives parts by position):
 *   badge paragraph(s) -> category paragraph (last before heading) -> H3 title ->
 *   price label paragraph -> price as bold-only paragraph -> instalment paragraph (optional) ->
 *   benefit paragraph (last text after price) -> CTA paragraph holding only a link.
 * The "N serviços disponíveis" count line is generated by the block and is not authored.
 */
const clean = (el) => (el ? el.textContent.replace(/\s+/g, ' ').trim() : '');

export default function parse(element, { document }) {
  const cells = [];
  const cards = element.querySelectorAll("a[class*='Cards_card']");

  cards.forEach((card) => {
    const href = card.getAttribute('href');

    // Cell 1: product image
    const imageCell = [];
    const img = card.querySelector("img[class*='styles_image']");
    if (img && img.getAttribute('src')) {
      const image = document.createElement('img');
      image.src = img.getAttribute('src');
      image.alt = img.getAttribute('alt') || '';
      imageCell.push(image);
    }

    // Cell 2: text in block order
    const body = [];
    const addP = (text) => {
      if (!text) return;
      const p = document.createElement('p');
      p.textContent = text;
      body.push(p);
    };

    // badges
    card.querySelectorAll("[class*='styles_tagItem']").forEach((tag) => addP(clean(tag)));

    // category eyebrow (always emitted right before the heading)
    addP(clean(card.querySelector("[class*='styles_preTitle']")));

    // title
    const titleText = clean(card.querySelector("[class*='styles_title']"));
    if (titleText) {
      const h3 = document.createElement('h3');
      h3.textContent = titleText;
      body.push(h3);
    }

    // price label, price (bold-only paragraph), instalments
    addP(clean(card.querySelector("[class*='styles_labelPrice']")));
    const priceText = clean(card.querySelector("[class*='styles_price_']"));
    if (priceText) {
      const p = document.createElement('p');
      const strong = document.createElement('strong');
      strong.textContent = priceText;
      p.append(strong);
      body.push(p);
    }
    addP(clean(card.querySelector("[class*='styles_instalmentText']")));

    // benefit (e.g. "20% de desconto com Cartão Porto Bank")
    const benefitBox = card.querySelector("[class*='styles_benefitsBox']");
    if (benefitBox) {
      const benefit = [...benefitBox.children].map(clean).filter(Boolean).join(' ');
      addP(benefit);
    }

    // CTA: source "button" is a span inside the card link; rebuild as link to the card href
    const ctaEl = card.querySelector('.desk-only .c-button') || card.querySelector('.c-button');
    const ctaText = clean(ctaEl) || 'Compre agora';
    if (href) {
      const p = document.createElement('p');
      const a = document.createElement('a');
      a.href = href;
      a.textContent = ctaText;
      p.append(a);
      body.push(p);
    }

    if (imageCell.length || body.length) cells.push([imageCell, body]);
  });

  const block = WebImporter.Blocks.createBlock(document, { name: 'cards-product', cells });
  element.replaceWith(block);
}
